/*
 * Сборка пояснительной записки (ПЗ) к курсовому проекту Voltix.
 * Документ растёт по разделам: содержимое каждого раздела хранится в массиве
 * children, при добавлении нового раздела файл просто пересобирается.
 * Оформление приближено к ГОСТ: Times New Roman 14 пт, интервал 1.5,
 * выравнивание по ширине, абзацный отступ 1.25 см, поля 30/15/20/20 мм.
 */
const fs = require('fs');
const {
  Document, Packer, Paragraph, TextRun, AlignmentType, LevelFormat,
  Table, TableRow, TableCell, WidthType, BorderStyle, ShadingType, VerticalAlign,
  ImageRun,
} = require('docx');

const CW = 9355; // ширина текста (поля 30/15 мм при A4)

const OUT = 'C:/Users/safik/Desktop/Сафиканов ПЗ Voltix.docx';

// ---- размерности ----
const PT = (p) => p * 2;             // пункты -> half-points
const FIRST_LINE = 709;              // 1.25 см в твипах
const LINE_15 = 360;                 // межстрочный 1.5

// ---- помощники ----
// Обычный абзац основного текста
function body(text, opts = {}) {
  return new Paragraph({
    alignment: AlignmentType.JUSTIFIED,
    spacing: { line: LINE_15, after: 0 },
    indent: { firstLine: FIRST_LINE },
    children: [new TextRun({ text })],
    ...opts,
  });
}

// Заголовок без нумерации (Введение, Заключение) — по центру, жирный
function headingCentered(text) {
  return new Paragraph({
    alignment: AlignmentType.CENTER,
    spacing: { line: LINE_15, before: 0, after: 240 },
    keepNext: true,
    children: [new TextRun({ text, bold: true })],
  });
}

// Нумерованный заголовок раздела (1 ..., 2 ...) — слева, жирный
function heading1(text) {
  return new Paragraph({
    alignment: AlignmentType.LEFT,
    spacing: { line: LINE_15, before: 240, after: 240 },
    indent: { firstLine: FIRST_LINE },
    keepNext: true,
    children: [new TextRun({ text, bold: true })],
  });
}

// Подзаголовок (1.1 ...) — слева, жирный
function heading2(text) {
  return new Paragraph({
    alignment: AlignmentType.LEFT,
    spacing: { line: LINE_15, before: 200, after: 200 },
    indent: { firstLine: FIRST_LINE },
    keepNext: true,
    children: [new TextRun({ text, bold: true })],
  });
}

// Пункт нумерованного списка источников
function sourceItem(text) {
  return new Paragraph({
    alignment: AlignmentType.JUSTIFIED,
    spacing: { line: LINE_15, after: 0 },
    numbering: { reference: 'sources', level: 0 },
    children: [new TextRun({ text })],
  });
}

// Пункт маркированного списка (с тире)
function bullet(text) {
  return new Paragraph({
    alignment: AlignmentType.JUSTIFIED,
    spacing: { line: LINE_15, after: 0 },
    numbering: { reference: 'bullets', level: 0 },
    children: [new TextRun({ text })],
  });
}

// Вставка изображения с подписью под ним
function figureImage(file, caption, w, h) {
  return [
    new Paragraph({
      alignment: AlignmentType.CENTER,
      spacing: { before: 120, after: 0, line: LINE_15 },
      keepNext: true,
      children: [new ImageRun({
        type: 'png',
        data: fs.readFileSync(file),
        transformation: { width: w, height: h },
        altText: { title: caption, description: caption, name: caption },
      })],
    }),
    new Paragraph({
      alignment: AlignmentType.CENTER,
      spacing: { before: 0, after: 120, line: LINE_15 },
      children: [new TextRun({ text: caption })],
    }),
  ];
}

// Маркер места под рисунок + подпись
function figurePlaceholder(caption) {
  return [
    new Paragraph({
      alignment: AlignmentType.CENTER,
      spacing: { line: LINE_15, before: 120, after: 0 },
      children: [new TextRun({ text: 'МЕСТО ДЛЯ РИСУНКА' })],
    }),
    new Paragraph({
      alignment: AlignmentType.CENTER,
      spacing: { line: LINE_15, before: 0, after: 120 },
      children: [new TextRun({ text: caption })],
    }),
  ];
}

// Подпись таблицы (над таблицей) / листинга
function tableCaption(text) {
  return new Paragraph({
    alignment: AlignmentType.LEFT,
    spacing: { before: 160, after: 60, line: LINE_15 },
    keepNext: true,
    children: [new TextRun({ text })],
  });
}
function listingCaption(text) {
  return new Paragraph({
    alignment: AlignmentType.LEFT,
    spacing: { before: 160, after: 60, line: LINE_15 },
    keepNext: true,
    children: [new TextRun({ text })],
  });
}

// Таблица с данными
const TB = { style: BorderStyle.SINGLE, size: 4, color: '000000' };
const TBORDERS = { top: TB, bottom: TB, left: TB, right: TB, insideHorizontal: TB, insideVertical: TB };
function tcell(text, width, { header = false, align = AlignmentType.LEFT } = {}) {
  return new TableCell({
    width: { size: width, type: WidthType.DXA },
    margins: { top: 40, bottom: 40, left: 90, right: 90 },
    shading: header ? { fill: 'E6E6E6', type: ShadingType.CLEAR } : undefined,
    verticalAlign: VerticalAlign.CENTER,
    children: [new Paragraph({
      alignment: align,
      spacing: { line: 240, after: 0 },
      children: [new TextRun({ text, bold: header, size: PT(12) })],
    })],
  });
}
function dataTable(colWidths, headerRow, rows) {
  const head = new TableRow({ tableHeader: true,
    children: headerRow.map((h, i) => tcell(h, colWidths[i], { header: true })) });
  const body = rows.map((r) => new TableRow({
    children: r.map((c, i) => tcell(c, colWidths[i])) }));
  return new Table({
    width: { size: colWidths.reduce((a, b) => a + b, 0), type: WidthType.DXA },
    columnWidths: colWidths,
    borders: TBORDERS,
    rows: [head, ...body],
  });
}

// Листинг из текстового файла (без проблем с экранированием)
function codeFromFile(file) {
  return codeBlock(fs.readFileSync(file, 'utf8').replace(/\r/g, '').replace(/\n$/, '').split('\n'));
}

// Листинг кода (моноширинный)
function codeBlock(lines) {
  return lines.map((l) => new Paragraph({
    alignment: AlignmentType.LEFT,
    spacing: { line: 240, after: 0 },
    children: [new TextRun({ text: l.length ? l : ' ', font: 'Courier New', size: PT(10) })],
  }));
}

